import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("ReportServlet");
    private static final String DB_URL = "jdbc:postgresql://db-primary:5432/analytics";
    private static final String DB_USER = "report_svc";
    private static final String DB_PASS = System.getenv("DB_PASSWORD");

    // Connection pool - reuses connections for performance
    private Connection getConnection() throws SQLException {
        Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
        conn.setAutoCommit(false);
        return conn;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        if ("export".equals(action)) {
            handleExport(req, resp);
        } else if ("summary".equals(action)) {
            handleSummary(req, resp);
        } else {
            resp.sendError(400, "Unknown action");
        }
    }

    private void handleExport(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String format = req.getParameter("fmt");

        // Build query with user-supplied department filter
        String query = "SELECT employee_id, full_name, salary, ssn, department, " +
                       "performance_rating FROM hr_records WHERE department = '" +
                       department + "' AND hire_date BETWEEN '" + startDate +
                       "' AND '" + endDate + "' ORDER BY employee_id";

        log.info("Export query for dept: " + department);

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("text/csv");
            resp.setHeader("Content-Disposition", "attachment; filename=report.csv");
            PrintWriter out = resp.getWriter();
            out.println("employee_id,full_name,salary,ssn,department,rating");

            while (rs.next()) {
                out.printf("%d,%s,%s,%s,%s,%s%n",
                    rs.getInt(1), rs.getString(2), rs.getBigDecimal(3),
                    rs.getString(4), rs.getString(5), rs.getString(6));
            }
            conn.commit();
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed: " + e.getMessage());
        }
    }

    private void handleSummary(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String groupBy = req.getParameter("group");
        // Only allow known groupings
        if (!"department".equals(groupBy) && !"quarter".equals(groupBy)) {
            resp.sendError(400, "Invalid grouping");
            return;
        }
        String query = "SELECT " + groupBy + ", COUNT(*), AVG(salary) FROM hr_records GROUP BY " + groupBy;

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            JSONArray arr = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("group", rs.getString(1));
                row.put("count", rs.getInt(2));
                row.put("avg_salary", rs.getDouble(3));
                arr.put(row);
            }
            resp.getWriter().write(arr.toString());
            conn.commit();
        } catch (SQLException e) {
            resp.sendError(500, "Summary failed");
        }
    }
}
